def info(p):
 i=Image.open(p);return {'path':str(p.relative_to(R)),'size':list(i.size),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'alpha_bounds':i.convert('RGBA').getbbox()}
u=next(x for x in json.loads((E/'catalog/production-units.json').read_text())['units']if x['id']=='class-15-ally')
