for f in [0,1,2]:
 shutil.copy2(B/f'candidate-v2/frame-{f:03d}.png',B/f'frames/frame-{f:03d}.png');atlas.alpha_composite(Image.open(B/f'frames/frame-{f:03d}.png').convert('RGBA'),(f*320,0))
